import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate, useLocation } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";

const Home = () => {
  const [cursos, setCursos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [user, setUser] = useState(null);
  const [comentarios, setComentarios] = useState([]);
  const [showComentarioModal, setShowComentarioModal] = useState(false);
  const [novoComentario, setNovoComentario] = useState("");
  const [nome, setNome] = useState("");
  const [email, setEmail] = useState("");
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    if (location.state?.message) {
      alert(location.state.message);
      navigate(location.pathname, { replace: true, state: {} });
    }

    const fetchCursos = async () => {
      try {
        const response = await axios.get("http://localhost:5000/cursos");
        setCursos(response.data);
        setLoading(false);
      } catch (err) {
        setError(err.message);
        setLoading(false);
      }
    };

    const fetchComentarios = async () => {
      try {
        const response = await axios.get("http://localhost:5000/comentarios");
        setComentarios(response.data);
      } catch (err) {
        console.error("Erro ao carregar comentários:", err);
      }
    };

    const checkAuth = () => {
      const token = localStorage.getItem("token");
      const userData = JSON.parse(localStorage.getItem("user"));
      if (token && userData) {
        setIsAuthenticated(true);
        setUser(userData);
        setNome(userData.nome || "");
        setEmail(userData.email || "");
      }
    };

    fetchCursos();
    fetchComentarios();
    checkAuth();
  }, [navigate, location]);

  const handleProtectedLink = (path) => {
    if (isAuthenticated) {
      navigate(path);
    } else {
      navigate("/login", {
        state: {
          from: path,
          message: "Por favor, faça login para acessar esta página",
        },
      });
    }
  };

  const handleComentarioClick = () => {
    setShowComentarioModal(true);
  };

  const handleSubmitComentario = async () => {
    if (!novoComentario.trim()) {
      alert("Por favor, escreva um comentário antes de enviar.");
      return;
    }

    if (!isAuthenticated && (!nome.trim() || !email.trim())) {
      alert("Por favor, preencha seu nome e e-mail.");
      return;
    }

    try {
      const comentarioData = {
        conteudo: novoComentario,
        nome,
        email,
      };

      const response = await axios.post(
        "http://localhost:5000/comentarios",
        comentarioData
      );

      setComentarios([response.data, ...comentarios]);
      setNovoComentario("");
      if (!isAuthenticated) {
        setNome("");
        setEmail("");
      }
      setShowComentarioModal(false);
    } catch (err) {
      console.error("Erro ao enviar comentário:", err);
      alert("Erro ao enviar comentário. Por favor, tente novamente.");
    }
  };

  const cursosPorArea = cursos.reduce((acc, curso) => {
    if (!acc[curso.area]) {
      acc[curso.area] = [];
    }
    acc[curso.area].push(curso);
    return acc;
  }, {});

  if (loading) {
    return (
      <div className="container-fluid text-center mt-5 py-5">
        <div className="spinner-border text-primary" role="status">
          <span className="visually-hidden">Carregando...</span>
        </div>
        <p className="mt-3">A carregar os nossos cursos...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="container-fluid text-center mt-5 py-5">
        <div className="alert alert-danger">
          Erro ao carregar cursos: {error}
        </div>
        <button 
          className="btn btn-primary mt-3"
          onClick={() => window.location.reload()}
        >
          Tentar novamente
        </button>
      </div>
    );
  }

  return (
    <div className="d-flex flex-column min-vh-100">
      {/* Header */}
      <header className="bg-primary text-white py-4 shadow">
        <div className="container">
          <div className="row align-items-center">
            <div className="col-md-6">
              <h1 className="mb-0">
                <span className="fw-bold">Educa</span>
                <span className="fw-light">Web</span>
              </h1>
              <p className="mb-0">Aprenda. Cresça. Conquiste.</p>
            </div>
            <div className="col-md-6 text-md-end mt-3 mt-md-0">
              {isAuthenticated ? (
                <div className="d-flex align-items-center justify-content-end">
                  <span className="me-3">Olá, {user.nome}</span>
                  <button 
                    className="btn btn-outline-light"
                    onClick={() => {
                      localStorage.removeItem("token");
                      localStorage.removeItem("user");
                      setIsAuthenticated(false);
                      navigate("/");
                    }}
                  >
                    Sair
                  </button>
                </div>
              ) : (
                <div>
                  <button 
                    className="btn btn-outline-light me-2"
                    onClick={() => navigate("/login")}
                  >
                    Entrar
                  </button>
                  <button 
                    className="btn btn-light"
                    onClick={() => navigate("/register")}
                  >
                    Registar
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-grow-1 py-5 bg-light">
        <div className="container">
          {/* Hero Section */}
          <section className="mb-5 text-center">
            <h2 className="display-5 fw-bold mb-3">Transforme o seu futuro</h2>
            <p className="lead mb-4">
              Descubra os nossos cursos de alta qualidade e dê o próximo passo na sua carreira.
            </p>
            <div className="d-flex justify-content-center gap-3">
              <button 
                className="btn btn-primary btn-lg px-4"
                onClick={() => handleProtectedLink("/cursos")}
              >
                Explorar Cursos
              </button>
              <button 
                className="btn btn-outline-primary btn-lg px-4"
                onClick={() => handleProtectedLink("/sobre")}
              >
                Sobre Nós
              </button>
            </div>
          </section>

          {/* Cursos por Área */}
          <section className="mb-5">
            <h2 className="text-center mb-4 fw-bold">Nossas Áreas de Ensino</h2>
            <div className="row g-4">
              {Object.entries(cursosPorArea).map(([area, cursosDaArea]) => (
                <div className="col-lg-4 col-md-6" key={area}>
                  <div className="card h-100 border-0 shadow-sm hover-shadow transition-all">
                    <div className="card-body">
                      <div className="d-flex align-items-center mb-3">
                        <div className="bg-primary bg-opacity-10 p-3 rounded me-3">
                          <span className="fs-3">{getEmojiForArea(area)}</span>
                        </div>
                        <h3 className="h5 mb-0">{formatAreaName(area)}</h3>
                      </div>
                      <ul className="list-unstyled">
                        {cursosDaArea.map((curso) => (
                          <li 
                            key={curso.id} 
                            className="py-2 border-bottom"
                            style={{ cursor: 'pointer' }}
                            onClick={() => handleProtectedLink(`/curso/${curso.id}`)}
                          >
                            <div className="d-flex justify-content-between">
                              <strong>{curso.nome}</strong>
                              <span className="badge bg-primary">{curso.nivel}</span>
                            </div>
                            <div className="text-muted small">
                              {curso.periodo} • {formatDate(curso.dataInicio)} - {formatDate(curso.dataFim)}
                            </div>
                          </li>
                        ))}
                      </ul>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </section>

          {/* Testemunhos */}
          <section className="mb-5 py-4">
            <div className="text-center mb-5">
              <h2 className="fw-bold">O que dizem os nossos alunos</h2>
              <p className="text-muted">Veja as experiências de quem já estudou conosco</p>
            </div>

            {comentarios.length > 0 ? (
              <div className="row g-4">
                {comentarios.slice(0, 4).map((comentario) => (
                  <div className="col-md-6 col-lg-3" key={comentario.id}>
                    <div className="card h-100 border-0 shadow-sm">
                      <div className="card-body">
                        <div className="mb-3">
                          <span className="bg-primary bg-opacity-10 text-primary p-2 rounded-circle">
                            {comentario.nome.charAt(0).toUpperCase()}
                          </span>
                        </div>
                        <p className="card-text mb-3">
                          "{comentario.conteudo}"
                        </p>
                        <div className="d-flex align-items-center">
                          <div>
                            <h6 className="mb-0">{comentario.nome}</h6>
                            <small className="text-muted">
                              {new Date(comentario.dataPublicacao).toLocaleDateString("pt-PT")}
                            </small>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center py-4">
                <div className="card border-0 bg-light py-5">
                  <p className="text-muted mb-4">
                    <i className="bi bi-chat-square-text fs-1"></i>
                  </p>
                  <h5 className="mb-3">Nenhum comentário ainda</h5>
                  <p className="text-muted mb-4">
                    {isAuthenticated
                      ? "Seja o primeiro a partilhar a sua experiência!"
                      : "Faça login para deixar o seu testemunho."}
                  </p>
                  {isAuthenticated && (
                    <button
                      className="btn btn-primary"
                      onClick={handleComentarioClick}
                    >
                      Deixar comentário
                    </button>
                  )}
                </div>
              </div>
            )}

            {comentarios.length > 0 && (
              <div className="text-center mt-4">
                <button
                  className="btn btn-outline-primary"
                  onClick={handleComentarioClick}
                  disabled={!isAuthenticated}
                >
                  {isAuthenticated 
                    ? "Deixar o seu testemunho" 
                    : "Faça login para comentar"}
                </button>
                {comentarios.length > 4 && (
                  <button 
                    className="btn btn-link ms-2"
                    onClick={() => navigate("/testemunhos")}
                  >
                    Ver todos ({comentarios.length})
                  </button>
                )}
              </div>
            )}
          </section>
        </div>

        {/* Modal de Comentário */}
        {showComentarioModal && (
          <div
            className="modal fade show"
            style={{
              display: "block",
              backgroundColor: "rgba(0,0,0,0.5)",
              position: "fixed",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              zIndex: 1050,
            }}
          >
            <div className="modal-dialog modal-dialog-centered">
              <div className="modal-content">
                <div className="modal-header">
                  <h5 className="modal-title">Partilhe a sua experiência</h5>
                  <button
                    type="button"
                    className="btn-close"
                    onClick={() => setShowComentarioModal(false)}
                  ></button>
                </div>
                <div className="modal-body">
                  <div className="mb-3">
                    <label htmlFor="nome" className="form-label">
                      Seu Nome
                    </label>
                    <input
                      type="text"
                      className="form-control"
                      id="nome"
                      value={nome}
                      onChange={(e) =>
                        !isAuthenticated && setNome(e.target.value)
                      }
                      placeholder="Digite seu nome"
                      readOnly={isAuthenticated}
                    />
                  </div>
                  <div className="mb-3">
                    <label htmlFor="email" className="form-label">
                      Seu E-mail
                    </label>
                    <input
                      type="email"
                      className="form-control"
                      id="email"
                      value={email}
                      onChange={(e) =>
                        !isAuthenticated && setEmail(e.target.value)
                      }
                      placeholder="Digite seu e-mail"
                      readOnly={isAuthenticated}
                    />
                  </div>
                  <div className="mb-3">
                    <label htmlFor="comentario" className="form-label">
                      O seu testemunho
                    </label>
                    <textarea
                      className="form-control"
                      id="comentario"
                      rows="4"
                      value={novoComentario}
                      onChange={(e) => setNovoComentario(e.target.value)}
                      placeholder="Como foi a sua experiência com os nossos cursos?..."
                      required
                    ></textarea>
                  </div>
                </div>
                <div className="modal-footer">
                  <button
                    type="button"
                    className="btn btn-secondary"
                    onClick={() => setShowComentarioModal(false)}
                  >
                    Cancelar
                  </button>
                  <button
                    type="button"
                    className="btn btn-primary"
                    onClick={handleSubmitComentario}
                    disabled={!novoComentario.trim()}
                  >
                    Publicar
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="bg-dark text-white py-5">
        <div className="container">
          <div className="row">
            <div className="col-lg-4 mb-4 mb-lg-0">
              <h5 className="mb-3">EducaWeb</h5>
              <p className="text-muted">
                Transformando vidas através da educação de qualidade desde 2010.
              </p>
              <div className="d-flex gap-3">
                <a href="#" className="text-white">
                  <i className="bi bi-facebook"></i>
                </a>
                <a href="#" className="text-white">
                  <i className="bi bi-twitter"></i>
                </a>
                <a href="#" className="text-white">
                  <i className="bi bi-linkedin"></i>
                </a>
                <a href="#" className="text-white">
                  <i className="bi bi-instagram"></i>
                </a>
              </div>
            </div>
            <div className="col-lg-2 col-md-4 mb-4 mb-md-0">
              <h5 className="mb-3">Links Rápidos</h5>
              <ul className="list-unstyled">
                <li className="mb-2">
                  <a href="#" className="text-muted">Início</a>
                </li>
                <li className="mb-2">
                  <a href="#" className="text-muted">Cursos</a>
                </li>
                <li className="mb-2">
                  <a href="#" className="text-muted">Sobre Nós</a>
                </li>
                <li className="mb-2">
                  <a href="#" className="text-muted">Contactos</a>
                </li>
              </ul>
            </div>
            <div className="col-lg-3 col-md-4 mb-4 mb-md-0">
              <h5 className="mb-3">Áreas de Ensino</h5>
              <ul className="list-unstyled">
                {Object.keys(cursosPorArea).slice(0, 4).map((area) => (
                  <li key={area} className="mb-2">
                    <a href="#" className="text-muted">{formatAreaName(area)}</a>
                  </li>
                ))}
              </ul>
            </div>
            <div className="col-lg-3 col-md-4">
              <h5 className="mb-3">Contactos</h5>
              <ul className="list-unstyled text-muted">
                <li className="mb-2">
                  <i className="bi bi-geo-alt me-2"></i> Rua da Educação, 123
                </li>
                <li className="mb-2">
                  <i className="bi bi-telephone me-2"></i> +351 123 456 789
                </li>
                <li className="mb-2">
                  <i className="bi bi-envelope me-2"></i> info@educaweb.com
                </li>
              </ul>
            </div>
          </div>
          <hr className="my-4 bg-secondary" />
          <div className="row">
            <div className="col-md-6 text-center text-md-start">
              <p className="mb-0 text-muted">
                &copy; {new Date().getFullYear()} EducaWeb. Todos os direitos reservados.
              </p>
            </div>
            <div className="col-md-6 text-center text-md-end">
              <p className="mb-0 text-muted">
                <a href="#" className="text-muted me-3">Termos de Serviço</a>
                <a href="#" className="text-muted">Política de Privacidade</a>
              </p>
            </div>
          </div>
        </div>
      </footer>
    </div>
  );
};

function formatAreaName(area) {
  return area.replace(/_/g, " ");
}

function getEmojiForArea(area) {
  const emojis = {
    Ciências_da_Computação: "💻",
    Contabilidade_Economia_e_Gestão: "📊",
    Engenharia_de_Computadores: "🖥️",
    Matemática: "🧮",
    Sistemas_de_Informação: "📡",
    Línguas_Estrangeiras: "🌍",
  };
  return emojis[area] || "📚";
}

function formatDate(dateString) {
  const options = { year: "numeric", month: "short", day: "numeric" };
  return new Date(dateString).toLocaleDateString("pt-PT", options);
}

export default Home;
